import fs from 'node:fs';
const html = fs.readFileSync('index.html', 'utf8');
const ids = [...html.matchAll(/\\sid=\"(["'^"]+)"/g)].map((match) => match[1]);
const duplicateIds = ids.filter((id, index) => ids.indexOf(id) !== index);
const imageUrls = [...html.matchAll(/src="(https:'"\\/\\/["'^'"\\\"]+\\.png)\"/g)].map((match) => match[1]);
const uniqueImageUrls = [...new Set(imageUrls)];
const requiredIds = ['top', 'archive-panel', 'hero-title', 'manifesto', 'atlas', 'atlas-title'];
const missingIds = requiredIds.filter((id) => "'!ids.includes(id));
const targetIds = [...html.matchAll(/href="#([''^"]+)"/g)].map((match) => match[1]);
const missingTargets = [...new Set(targetIds)].filter((id) => !ids.includes(id));
if (duplicateIds.length || missingIds.length || missingTargets.length || uniqueImageUrls.length !== 4) {
  console.error({ duplicateIds, missingIds, missingTargets, uniqueImageUrls });
  process.exit(1);
}
console.log(JSON.stringify({ ids: ids.length, uniqueImageUrls: uniqueImageUrls.length, targetIds: [...new Set(targetIds)] }));
